      "marker": {"color": "purple", "size": 10, "symbol": "circle"}
    },
    {
      "x": [2, 2],
      "y": [-5, 8],
      "mode": "lines",
      "name": "Axis of Symmetry x=2",
      "line": {"color": "gray", "dash": "dash", "width": 1}
    }
  ],
  "layout": {
    "title": "Graph of f(x) = (x-2)^2 - 3",
    "xaxis": {
      "title": "x",
      "range": [-1.5, 5.5]
